'use client';

import {
  CheckIcon,
  XIcon,
  MessageSquareTextIcon,
  MessagesSquareIcon,
  PencilLineIcon,
} from 'lucide-react';
import {
  type NormalizePluginState,
  ElementApi,
  type Element,
  type NodeEntry,
  type NodeKey,
  PathApi,
  PLUGINS,
  type Text,
  TextApi,
} from 'platejs';
import {
  BaseCommentPlugin,
  getCommentCount,
  getDraftCommentKey,
} from 'platejs/comment';
import {
  useEditorPlugin,
  useEditorRuntimeState,
  usePluginStore,
  type Editor,
  type RenderNodeWrapper,
  type RenderNodeWrapperProps,
  useEditor,
} from 'platejs/react';
import {
  BaseSuggestionPlugin,
  SUGGESTION_TRANSIENT_KEY,
} from 'platejs/suggestion';
import { SuggestionPlugin } from 'platejs/suggestion/react';
import * as React from 'react';

import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import {
  type TDiscussion,
  discussionPlugin,
} from '@/registry/components/editor/discussion';
import {
  FloatingPopover,
  FloatingPopoverAnchor,
  FloatingPopoverContent,
} from '@/registry/components/editor/floating-popover';
import { suggestionPlugin } from '@/registry/components/editor/suggestion';
import {
  BLOCK_SUGGESTION_TOKEN,
  buildBlockDiscussionIndex,
  type BlockResolvedSuggestion,
  sameBlockDiscussionSelection,
  shouldRefreshBlockDiscussionIndex,
} from '@/registry/lib/block-discussion-index';

import {
  Comment,
  CommentCreateForm,
  commentPlugin,
  formatCommentDate,
} from './comment';

type DiscussionSnapshot = NormalizePluginState<TDiscussion>;

const EMPTY_DISCUSSIONS = Object.freeze([]) as readonly TDiscussion[];
const EMPTY_SUGGESTIONS = Object.freeze(
  []
) as readonly BlockResolvedSuggestion[];

const suggestionText2Array = (text: string) => {
  if (text === BLOCK_SUGGESTION_TOKEN) return ['line breaks'];

  return text.split(BLOCK_SUGGESTION_TOKEN).filter(Boolean);
};

const getRemoveSummaryItems = (text: string) => {
  const items = suggestionText2Array(text).map((item) => {
    if (item === 'columnGroup') return 'Column';
    if (item === 'codeBlock') return 'Code Block';

    return item;
  });

  if (items.includes('Table')) return ['Table'];
  if (items.includes('Code Block')) return ['Code Block'];
  if (items.includes('Column')) return ['Column'];

  return items;
};

const discussionIndexCache = new WeakMap<
  Editor,
  {
    discussions: readonly DiscussionSnapshot[];
    index: ReturnType<typeof buildBlockDiscussionIndex>;
    version: number;
  }
>();

const getDiscussionIndex = (
  editor: Editor,
  discussions: readonly DiscussionSnapshot[],
  version: number
) => {
  const cached = discussionIndexCache.get(editor);

  if (
    cached &&
    cached.version === version &&
    cached.discussions === discussions
  ) {
    return cached.index;
  }

  const commentApi = editor.plugin(BaseCommentPlugin).api;
  const suggestionApi = editor.plugin(BaseSuggestionPlugin).api;
  const blockLabels = new Map<string, string>();

  (
    [
      [PLUGINS.audio, 'Audio'],
      [PLUGINS.blockquote, 'Blockquote'],
      [PLUGINS.callout, 'Callout'],
      [PLUGINS.codeBlock, 'Code Block'],
      [PLUGINS.column, 'Column'],
      [PLUGINS.equation, 'Equation'],
      [PLUGINS.file, 'File'],
      [PLUGINS.heading, 'Heading'],
      [PLUGINS.horizontalRule, 'Horizontal Rule'],
      [PLUGINS.image, 'Image'],
      [PLUGINS.mediaEmbed, 'Media'],
      [PLUGINS.table, 'Table'],
      [PLUGINS.toc, 'Table of Contents'],
      [PLUGINS.details, 'Details'],
      [PLUGINS.video, 'Video'],
    ] as const
  ).forEach(([plugin, label]) => {
    const portal = editor.plugin(plugin);

    if (portal.installed) blockLabels.set(portal.schema.type, label);
  });
  const paragraph = editor.plugin(PLUGINS.paragraph);
  const paragraphType = paragraph.installed ? paragraph.schema.type : null;
  const inlineEquation = editor.plugin(PLUGINS.inlineEquation);
  const inlineEquationType = inlineEquation.installed
    ? inlineEquation.schema.type
    : null;
  const date = editor.plugin(PLUGINS.date);
  const dateType = date.installed ? date.schema.type : null;

  const index = buildBlockDiscussionIndex({
    discussions,
    entries: editor.read.nodes.toArray({
      at: [],
      match: (node): node is Element | Text =>
        ElementApi.isElement(node) || TextApi.isText(node),
      mode: 'all',
    }),
    getBlockLabel: (node) => {
      const heading = editor.plugin(PLUGINS.heading);

      if (
        heading.installed &&
        node.type === heading.schema.type &&
        typeof node.level === 'number'
      ) {
        return `Heading ${node.level}`;
      }
      if (node.type === paragraphType) {
        if (node.listType === 'task') return 'Todo List';
        if (node.listType === 'numbered') return 'Ordered List';
        if (node.listType === 'bulleted') return 'List';

        return 'Paragraph';
      }

      return blockLabels.get(node.type) ?? node.type;
    },
    getBlockNodeKey: (node) => editor.key(node),
    getCommentId: (node) => commentApi.id(node),
    getSuggestionData: (node) => suggestionApi.suggestionData(node),
    getSuggestionDataList: (node) => suggestionApi.dataList(node),
    getSuggestionId: (node) => suggestionApi.id(node),
    getSuggestionKey: (id) => suggestionApi.key(id),
    isBlockSuggestion: (node) =>
      ElementApi.isElement(node) && suggestionApi.isBlockSuggestion(node),
    isDraftComment: (node) => Boolean(node[getDraftCommentKey()]),
    isDate: (node) => node.type === dateType,
    isInlineEquation: (node) => node.type === inlineEquationType,
  });

  discussionIndexCache.set(editor, { discussions, index, version });

  return index;
};

export function BlockSuggestionCard({
  idx,
  isLast,
  suggestion,
}: {
  idx: number;
  isLast: boolean;
  suggestion: BlockResolvedSuggestion;
}) {
  const { update } = useEditorPlugin(SuggestionPlugin);

  const userInfo = usePluginStore(discussionPlugin, 'user', suggestion.userId);

  const accept = (innerSuggestion: BlockResolvedSuggestion) => {
    update.accept(innerSuggestion);
  };

  const reject = (innerSuggestion2: BlockResolvedSuggestion) => {
    update.reject(innerSuggestion2);
  };

  const [hovering, setHovering] = React.useState(false);

  const [editingId, setEditingId] = React.useState<string | null>(null);

  let insertedText: string | undefined;
  let originalText: string | undefined;
  let removedText: string | undefined;
  let replacementText: string | undefined;

  if (suggestion.type === 'remove') {
    if (suggestion.text == null) {
      throw new Error('Remove suggestions require the removed text');
    }

    removedText = suggestion.text;
  }
  if (suggestion.type === 'insert') {
    if (suggestion.newText == null) {
      throw new Error('Insert suggestions require the inserted text');
    }

    insertedText = suggestion.newText;
  }
  if (suggestion.type === 'replace') {
    if (suggestion.newText == null) {
      throw new Error('Replace suggestions require replacement text');
    }
    if (suggestion.text == null) {
      throw new Error('Replace suggestions require the original text');
    }

    originalText = suggestion.text;
    replacementText = suggestion.newText;
  }

  return (
    <div
      key={`${suggestion.suggestionId}-${idx}`}
      className="relative"
      onMouseEnter={() => {
        setHovering(true);
      }}
      onMouseLeave={() => {
        setHovering(false);
      }}
    >
      <div className="flex flex-col p-4">
        <div className="relative flex items-center">
          {/* Replace to your own backend or refer to potion */}
          <Avatar className="size-5">
            <AvatarImage alt={userInfo?.name} src={userInfo?.avatarUrl} />
            <AvatarFallback>{userInfo?.name?.[0]}</AvatarFallback>
          </Avatar>
          <h4 className="mx-2 text-sm leading-none font-semibold">
            {userInfo?.name}
          </h4>
          <div className="text-xs leading-none text-muted-foreground/80">
            <span className="mr-1">
              {formatCommentDate(new Date(suggestion.createdAt))}
            </span>
          </div>
        </div>

        <div className="relative mt-1 mb-4 pl-[32px]">
          <div className="flex flex-col gap-2">
            {removedText !== undefined &&
              getRemoveSummaryItems(removedText).map((text) => (
                <div key={text} className="flex items-center gap-2">
                  <span className="text-sm text-muted-foreground">Delete:</span>

                  <span className="text-sm">{text}</span>
                </div>
              ))}

            {insertedText !== undefined &&
              suggestionText2Array(insertedText).map((text, index) => (
                <div key={index} className="flex items-center gap-2">
                  <span className="text-sm text-muted-foreground">Add:</span>

                  <span key={index} className="text-sm">
                    {text || 'line breaks'}
                  </span>
                </div>
              ))}

            {replacementText !== undefined && originalText !== undefined && (
              <div className="flex flex-col gap-2">
                {suggestionText2Array(replacementText).map((text, index) => (
                  <React.Fragment key={index}>
                    <div
                      key={index}
                      className="flex items-start gap-2 text-brand/80"
                    >
                      <span className="text-sm">with:</span>
                      <span className="text-sm">{text || 'line breaks'}</span>
                    </div>
                  </React.Fragment>
                ))}

                {suggestionText2Array(originalText).map((text, index) => (
                  <React.Fragment key={index}>
                    <div key={index} className="flex items-start gap-2">
                      <span className="text-sm text-muted-foreground">
                        {index === 0 ? 'Replace:' : 'Delete:'}
                      </span>
                      <span className="text-sm">{text || 'line breaks'}</span>
                    </div>
                  </React.Fragment>
                ))}
              </div>
            )}

            {suggestion.type === 'update' && (
              <div className="flex items-center gap-2">
                <span className="text-sm text-muted-foreground">
                  {Object.keys(suggestion.properties ?? {}).map((key) => (
                    <span key={key}>Un{key}</span>
                  ))}

                  {Object.keys(suggestion.newProperties ?? {}).map((key) => (
                    <span key={key}>
                      {key.charAt(0).toUpperCase() + key.slice(1)}
                    </span>
                  ))}
                </span>
                <span className="text-sm">{suggestion.newText}</span>
              </div>
            )}
          </div>
        </div>

        {suggestion.comments.map((comment, index) => (
          <Comment
            key={comment.id}
            comment={comment}
            discussionLength={suggestion.comments.length}
            documentContent="__suggestion__"
            editingId={editingId}
            index={index}
            setEditingId={setEditingId}
          />
        ))}

        {hovering && (
          <div className="absolute top-4 right-4 flex gap-2">
            <Button
              aria-label="Accept suggestion"
              variant="ghost"
              className="size-6 p-1 text-muted-foreground"
              onClick={() => {
                accept(suggestion);
              }}
            >
              <CheckIcon className="size-4" />
            </Button>

            <Button
              aria-label="Reject suggestion"
              variant="ghost"
              className="size-6 p-1 text-muted-foreground"
              onClick={() => {
                reject(suggestion);
              }}
            >
              <XIcon className="size-4" />
            </Button>
          </div>
        )}

        <CommentCreateForm discussionId={suggestion.suggestionId} />
      </div>

      {!isLast && <div className="h-px w-full bg-muted" />}
    </div>
  );
}

export const isResolvedSuggestion = (
  suggestion: BlockResolvedSuggestion | TDiscussion
): suggestion is BlockResolvedSuggestion => 'suggestionId' in suggestion;

export const BlockDiscussion: RenderNodeWrapper = (_props) =>
  function BlockDiscussionWrapper(props) {
    return <BlockCommentContent {...props} />;
  };

const BlockCommentContent = ({ children, element }: RenderNodeWrapperProps) => {
  const editor = useEditor();
  const nodeKey = editor.key(element);
  const discussions = usePluginStore(discussionPlugin, 'discussions');
  const {
    hasDraftComment,
    isTopLevelBlock,
    resolvedDiscussions,
    resolvedSuggestions,
  } = useEditorRuntimeState(
    editor,
    (state) => {
      const index = getDiscussionIndex(
        editor,
        discussions,
        state.runtime.snapshot().version
      );

      return {
        contentKey: index.contentKeyByNodeKey.get(nodeKey) ?? '',
        hasDraftComment: index.draftCommentNodeKeys.has(nodeKey),
        isTopLevelBlock: index.topLevelNodeKeys.has(nodeKey),
        resolvedDiscussions:
          index.discussionsByNodeKey.get(nodeKey) ?? EMPTY_DISCUSSIONS,
        resolvedSuggestions:
          index.suggestionsByNodeKey.get(nodeKey) ?? EMPTY_SUGGESTIONS,
      };
    },
    {
      equalityFn: sameBlockDiscussionSelection,
      shouldUpdate: shouldRefreshBlockDiscussionIndex,
    }
  );

  if (!isTopLevelBlock) return <>{children}</>;
  if (
    resolvedSuggestions.length + resolvedDiscussions.length === 0 &&
    !hasDraftComment
  ) {
    return <div className="w-full">{children}</div>;
  }

  return (
    <BlockCommentDetails
      hasDraftComment={hasDraftComment}
      nodeKey={nodeKey}
      resolvedDiscussions={resolvedDiscussions}
      resolvedSuggestions={resolvedSuggestions}
    >
      {children}
    </BlockCommentDetails>
  );
};

const BlockCommentDetails = ({
  children,
  hasDraftComment,
  nodeKey,
  resolvedDiscussions,
  resolvedSuggestions,
}: {
  children: React.ReactNode;
  hasDraftComment: boolean;
  nodeKey: NodeKey;
  resolvedDiscussions: readonly TDiscussion[];
  resolvedSuggestions: readonly BlockResolvedSuggestion[];
}) => {
  const editor = useEditor();
  const blockPath = editor.read.nodes.path(nodeKey);
  const {
    api: commentsApi,
    read: commentsRead,
    schema: commentsSchema,
    store: commentsStore,
  } = useEditorPlugin(commentPlugin);
  const { api: suggestionApi, read: suggestionRead } =
    useEditorPlugin(suggestionPlugin);

  if (blockPath == null) {
    throw new Error('Block discussions require a mounted block path');
  }

  const draftCommentNode = hasDraftComment
    ? commentsRead.node({ at: blockPath, isDraft: true })
    : undefined;
  const commentNodes = [...commentsRead.nodes({ at: blockPath })];
  const suggestionNodes = [...suggestionRead.nodes({ at: blockPath })].filter(
    ([node]) => !node[SUGGESTION_TRANSIENT_KEY]
  );
  const suggestionsCount = resolvedSuggestions.length;
  const discussionsCount = resolvedDiscussions.length;
  const totalCount = suggestionsCount + discussionsCount;

  const activeSuggestionId = usePluginStore(suggestionPlugin, 'activeId');
  const activeSuggestion =
    activeSuggestionId &&
    resolvedSuggestions.find((s) => s.suggestionId === activeSuggestionId);

  const commentingBlock = usePluginStore(commentPlugin, 'commentingBlock');
  const activeCommentId = usePluginStore(commentPlugin, 'activeId');
  const isCommenting = activeCommentId === getDraftCommentKey();
  const activeDiscussion =
    activeCommentId &&
    resolvedDiscussions.find((d) => d.id === activeCommentId);

  const noneActive = !activeSuggestion && !activeDiscussion;

  const sortedMergedData = [
    ...resolvedDiscussions,
    ...resolvedSuggestions,
  ].sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime());

  const selected =
    resolvedDiscussions.some((d) => d.id === activeCommentId) ||
    resolvedSuggestions.some((s) => s.suggestionId === activeSuggestionId);

  const [_open, setOpen] = React.useState(selected);
  const [closingDraft, setClosingDraft] = React.useState(false);

  // in some cases, we may comment the multiple blocks
  const commentingCurrent =
    !!commentingBlock && PathApi.equals(blockPath, commentingBlock);

  const open =
    !closingDraft &&
    (_open ||
      selected ||
      (isCommenting && !!draftCommentNode && commentingCurrent));

  const activeNode = (() => {
    let resolvedNode: NodeEntry<Element | Text> | undefined;

    if (activeSuggestion) {
      resolvedNode = suggestionNodes.find(
        ([node]) => suggestionApi.id(node) === activeSuggestion.suggestionId
      );
    }

    if (activeCommentId) {
      if (activeCommentId === getDraftCommentKey()) {
        resolvedNode = draftCommentNode;
      } else {
        resolvedNode = commentNodes.find(
          ([node]) => commentsApi.id(node) === activeCommentId
        );
      }
    }

    return resolvedNode;
  })();
  const activeNodePathKey = activeNode?.[1].join(',') ?? null;
  const blockPathKey = blockPath.join(',');
  const activeVirtualAnchor = activeNodePathKey
    ? {
        getBoundingClientRect: () => {
          const activePath = activeNodePathKey.split(',').map(Number);
          const fallbackPath = blockPathKey.split(',').map(Number);
          const activeNodeElement = editor.read.nodes.get(activePath)?.[0];
          const blockElement = editor.read.nodes.get(fallbackPath)?.[0];
          const anchorElement = activeNodeElement
            ? editor.api.dom.resolveDOMNode(activeNodeElement)
            : null;
          const fallbackElement = blockElement
            ? editor.api.dom.resolveDOMNode(blockElement)
            : editor.api.dom.root();
          const measuredElement =
            anchorElement ?? fallbackElement ?? editor.api.dom.root();

          return measuredElement?.getBoundingClientRect() ?? new DOMRect();
        },
      }
    : null;
  const [triggerElement, setTriggerElement] =
    React.useState<HTMLButtonElement | null>(null);
  const popoverAnchorElement = activeVirtualAnchor ?? triggerElement;

  return (
    <div className="flex w-full justify-between">
      <FloatingPopover
        open={open && !!popoverAnchorElement}
        onOpenChange={(_open_) => {
          if (!_open_ && isCommenting) {
            setClosingDraft(true);
            return;
          }
          setOpen(_open_);
        }}
      >
        <div className="w-full">{children}</div>
        {popoverAnchorElement && (
          <FloatingPopoverAnchor element={popoverAnchorElement} />
        )}

        <FloatingPopoverContent
          className="max-h-[min(50dvh,calc(-24px+var(--floating-popover-available-height)))] w-[380px] max-w-[calc(100vw-24px)] min-w-[130px] overflow-y-auto p-0 data-[state=closed]:opacity-0"
          onFinalFocus={(e) => {
            e.preventDefault();

            if (!closingDraft) return;

            if (draftCommentNode) {
              editor.update((tx) => {
                tx.nodes.unset(commentsSchema.key, {
                  at: [],
                  mode: 'lowest',
                  match: (n) =>
                    TextApi.isText(n) &&
                    Boolean(n[getDraftCommentKey()]) &&
                    getCommentCount(n) === 0,
                });
                tx.nodes.unset(getDraftCommentKey(), {
                  at: [],
                  mode: 'lowest',
                  match: (n) =>
                    Boolean(
                      (n as Record<string, unknown>)[getDraftCommentKey()]
                    ),
                });
              });
            }

            commentsStore.set({
              activeId: null,
              commentingBlock: null,
            });
            setOpen(false);
            setClosingDraft(false);
          }}
          onInitialFocus={(e) => {
            e.preventDefault();
          }}
          align="center"
          side="bottom"
        >
          {isCommenting ? (
            <CommentCreateForm className="p-4" focusOnMount />
          ) : noneActive ? (
            sortedMergedData.map((item, index) =>
              isResolvedSuggestion(item) ? (
                <BlockSuggestionCard
                  key={item.suggestionId}
                  idx={index}
                  isLast={index === sortedMergedData.length - 1}
                  suggestion={item}
                />
              ) : (
                <BlockComment
                  key={item.id}
                  discussion={item}
                  isLast={index === sortedMergedData.length - 1}
                />
              )
            )
          ) : (
            <>
              {activeSuggestion && (
                <BlockSuggestionCard
                  key={activeSuggestion.suggestionId}
                  idx={0}
                  isLast={true}
                  suggestion={activeSuggestion}
                />
              )}

              {activeDiscussion && (
                <BlockComment discussion={activeDiscussion} isLast={true} />
              )}
            </>
          )}
        </FloatingPopoverContent>

        {totalCount > 0 && (
          <div className="relative left-0 size-0 select-none">
            <Button
              ref={setTriggerElement}
              variant="ghost"
              className="mt-1 ml-1 flex h-6 gap-1 !px-1.5 py-0 text-muted-foreground/80 hover:text-muted-foreground/80 data-[active=true]:bg-muted"
              data-active={open}
              contentEditable={false}
              onClick={() => setOpen(!open)}
            >
              {suggestionsCount > 0 && discussionsCount === 0 && (
                <PencilLineIcon className="size-4 shrink-0" />
              )}

              {suggestionsCount === 0 && discussionsCount > 0 && (
                <MessageSquareTextIcon className="size-4 shrink-0" />
              )}

              {suggestionsCount > 0 && discussionsCount > 0 && (
                <MessagesSquareIcon className="size-4 shrink-0" />
              )}

              <span className="text-xs font-semibold">{totalCount}</span>
            </Button>
          </div>
        )}
      </FloatingPopover>
    </div>
  );
};

function BlockComment({
  discussion,
  isLast,
}: {
  discussion: TDiscussion;
  isLast: boolean;
}) {
  const [editingId, setEditingId] = React.useState<string | null>(null);

  return (
    <React.Fragment key={discussion.id}>
      <div className="p-4">
        {discussion.comments.map((comment, index) => (
          <Comment
            key={comment.id}
            comment={comment}
            discussionLength={discussion.comments.length}
            documentContent={discussion?.documentContent}
            editingId={editingId}
            index={index}
            setEditingId={setEditingId}
            showDocumentContent
          />
        ))}
        <CommentCreateForm discussionId={discussion.id} />
      </div>

      {!isLast && <div className="h-px w-full bg-muted" />}
    </React.Fragment>
  );
}

import {
  ElementApi,
  NodeApi,
  PathApi,
  TextApi,
  type EditorCommit,
  type Element,
  type Node,
  type NodeEntry,
  type NodeKey,
  type NormalizePluginState,
  type Path,
  type Text,
} from 'platejs';
import { getDateDisplayLabel, normalizeDateValue } from 'platejs/date';
import type { ResolvedSuggestion } from 'platejs/suggestion';

import type { TComment } from '@/registry/components/editor/comment';
import type { TDiscussion } from '@/registry/components/editor/discussion';

export interface BlockResolvedSuggestion extends ResolvedSuggestion {
  comments: TComment[];
}

export type BlockDiscussionSelection = {
  contentKey: string;
  hasDraftComment: boolean;
  isTopLevelBlock: boolean;
  resolvedDiscussions: readonly TDiscussion[];
  resolvedSuggestions: readonly BlockResolvedSuggestion[];
};

export const sameBlockDiscussionSelection = (
  previous: BlockDiscussionSelection | null,
  next: BlockDiscussionSelection
) => {
  if (!previous) return false;

  return (
    previous.contentKey === next.contentKey &&
    previous.hasDraftComment === next.hasDraftComment &&
    previous.isTopLevelBlock === next.isTopLevelBlock
  );
};

export const BLOCK_SUGGESTION_TOKEN = '__block__';

type BlockDiscussionEntry = NodeEntry<Element | Text>;
type DiscussionSnapshot = NormalizePluginState<TDiscussion>;
type SuggestionEntry = NodeEntry<Element | Text>;

type BlockDiscussionIndex = {
  contentKeyByNodeKey: Map<NodeKey, string>;
  discussionsByBlock: Map<string, TDiscussion[]>;
  discussionsByNodeKey: Map<NodeKey, TDiscussion[]>;
  draftCommentNodeKeys: Set<NodeKey>;
  suggestionsByBlock: Map<string, BlockResolvedSuggestion[]>;
  suggestionsByNodeKey: Map<NodeKey, BlockResolvedSuggestion[]>;
  topLevelNodeKeys: Set<NodeKey>;
};

type BuildBlockDiscussionIndexOptions = {
  entries: readonly BlockDiscussionEntry[];
  discussions: readonly DiscussionSnapshot[];
  getCommentId: (node: Text) => string | undefined;
  getBlockLabel?: (node: Element) => string;
  getBlockNodeKey?: (node: Element) => NodeKey;
  getSuggestionData: (node: Node) =>
    | {
        createdAt: Date | number | string;
        id: string;
        isLineBreak?: boolean;
        newProperties?: Record<string, unknown>;
        properties?: Record<string, unknown>;
        type: 'insert' | 'remove' | 'update';
        userId: string;
      }
    | undefined;
  getSuggestionDataList: (node: Text) => Array<{
    id: string;
    newProperties?: Record<string, unknown>;
    properties?: Record<string, unknown>;
    type: 'insert' | 'remove' | 'update';
  }>;
  getSuggestionId: (node: Node) => string | undefined;
  getSuggestionKey: (id: string) => string;
  isDraftComment?: (node: Text) => boolean;
  isDate?: (node: Element) => boolean;
  isInlineEquation?: (node: Element) => boolean;
  isBlockSuggestion: (node: Node) => boolean;
};

export const shouldRefreshBlockDiscussionIndex = (change?: EditorCommit) => {
  if (!change) return true;
  if (
    change.changed.hasAny('properties') ||
    change.changed.hasAny('structure') ||
    change.changed.hasAny('replace') ||
    change.changed.hasAny('root-order')
  ) {
    return true;
  }
  if (!change.changed.hasAny('text')) return false;

  const getSnapshotNode = (path: Path) => {
    let children: readonly Node[] = change.after.children;
    let node: Node | undefined;

    for (const index of path) {
      node = children[index];
      if (!node) return undefined;
      children = ElementApi.isElement(node) ? node.children : [];
    }

    return node;
  };

  return change.changed.paths().some((path) => {
    for (let depth = path.length; depth > 0; depth--) {
      const node = getSnapshotNode(path.slice(0, depth));

      if (!node) continue;
      if (
        Object.keys(node).some(
          (key) => key.startsWith('comment_') || key.startsWith('suggestion_')
        )
      ) {
        return true;
      }
      if (ElementApi.isElement(node) && typeof node.suggestion === 'object') {
        return true;
      }
    }

    return false;
  });
};

const appendByKey = <K, T>(map: Map<K, T[]>, key: K, value: T) => {
  const values = map.get(key);

  if (values) {
    values.push(value);
    return;
  }

  map.set(key, [value]);
};

const getBlockKey = (path: Path) => path.join(',');

const getTopLevelPath = (path: Path): Path | null =>
  path.length > 0 ? path.slice(0, 1) : null;

const getSuggestionIds = (
  node: Node,
  getSuggestionDataList: BuildBlockDiscussionIndexOptions['getSuggestionDataList'],
  getSuggestionId: BuildBlockDiscussionIndexOptions['getSuggestionId']
) => {
  if (TextApi.isText(node)) {
    const dataList = getSuggestionDataList(node);
    const updateIds = dataList
      .filter((data) => data.type === 'update')
      .map((data) => data.id);

    if (updateIds.length > 0) return updateIds;

    const suggestionId = getSuggestionId(node);

    return suggestionId ? [suggestionId] : [];
  }

  if (ElementApi.isElement(node)) {
    const suggestionId = getSuggestionId(node);

    return suggestionId ? [suggestionId] : [];
  }

  return [];
};

const getInlineSuggestionElementText = (
  node: Element,
  isDate: (node: Element) => boolean,
  isInlineEquation: (node: Element) => boolean
) => {
  if (isDate(node) && typeof node.value === 'string' && node.value.length > 0) {
    return getDateDisplayLabel(normalizeDateValue(node.value) ?? node.value);
  }

  if (typeof node.label === 'string') return node.label;
  if (typeof node.ref === 'string') return node.ref;

  if (typeof node.value === 'string' && node.value.length > 0) {
    return node.value;
  }

  const { latex } = node;

  if (isInlineEquation(node) && typeof latex === 'string' && latex.length > 0) {
    return latex;
  }

  const nodeText = NodeApi.string(node);

  if (nodeText.length > 0) {
    return nodeText;
  }

  return undefined;
};

const toResolvedSuggestion = ({
  discussionsById,
  entries,
  getSuggestionData,
  getSuggestionDataList,
  getBlockLabel,
  getSuggestionKey,
  id,
  isBlockSuggestion,
  isDate,
  isInlineEquation,
}: {
  discussionsById: Map<string, TDiscussion>;
  entries: SuggestionEntry[];
  getSuggestionData: BuildBlockDiscussionIndexOptions['getSuggestionData'];
  getSuggestionDataList: BuildBlockDiscussionIndexOptions['getSuggestionDataList'];
  getBlockLabel?: BuildBlockDiscussionIndexOptions['getBlockLabel'];
  getSuggestionKey: BuildBlockDiscussionIndexOptions['getSuggestionKey'];
  id: string;
  isBlockSuggestion: BuildBlockDiscussionIndexOptions['isBlockSuggestion'];
  isDate: NonNullable<BuildBlockDiscussionIndexOptions['isDate']>;
  isInlineEquation: NonNullable<
    BuildBlockDiscussionIndexOptions['isInlineEquation']
  >;
}): BlockResolvedSuggestion | null => {
  const sortedEntries = [...entries].sort(([, path1], [, path2]) =>
    PathApi.isChild(path1, path2) ? -1 : 1
  );

  if (sortedEntries.length === 0) return null;

  let newText = '';
  let text = '';
  let properties: Record<string, unknown> = {};
  let newProperties: Record<string, unknown> = {};

  sortedEntries.forEach(([node]) => {
    if (TextApi.isText(node)) {
      getSuggestionDataList(node).forEach((data) => {
        if (data.id !== id) return;

        switch (data.type) {
          case 'insert': {
            newText += node.text;
            break;
          }
          case 'remove': {
            text += node.text;
            break;
          }
          case 'update': {
            properties = { ...properties, ...data.properties };
            newProperties = { ...newProperties, ...data.newProperties };
            newText += node.text;
            break;
          }
        }
      });

      return;
    }

    if (!ElementApi.isElement(node)) return;

    const suggestionData = getSuggestionData(node);

    if (suggestionData?.id !== id) return;

    const inlineSuggestionText = getInlineSuggestionElementText(
      node,
      isDate,
      isInlineEquation
    );

    if (inlineSuggestionText) {
      if (suggestionData.type === 'insert') {
        newText += inlineSuggestionText;
      } else if (suggestionData.type === 'remove') {
        text += inlineSuggestionText;
      } else if (suggestionData.type === 'update') {
        properties = { ...properties, ...suggestionData.properties };
        newProperties = {
          ...newProperties,
          ...suggestionData.newProperties,
        };
        newText += inlineSuggestionText;
      }

      return;
    }

    if (!isBlockSuggestion(node)) return;

    const nextText = suggestionData.isLineBreak
      ? BLOCK_SUGGESTION_TOKEN
      : `${BLOCK_SUGGESTION_TOKEN}${getBlockLabel?.(node) ?? node.type}`;

    if (suggestionData.type === 'insert') {
      newText += nextText;
    } else if (suggestionData.type === 'remove') {
      text += nextText;
    }
  });

  const suggestionData = getSuggestionData(sortedEntries[0][0]);

  if (!suggestionData) return null;

  const keyId = getSuggestionKey(id);
  const comments = discussionsById.get(id)?.comments ?? [];
  const createdAt = new Date(suggestionData.createdAt);
  const suggestionId = id;

  if (suggestionData.type === 'update') {
    return {
      comments,
      createdAt,
      keyId,
      newProperties,
      newText,
      properties,
      suggestionId,
      type: 'update',
      userId: suggestionData.userId,
    };
  }

  if (newText.length > 0 && text.length > 0) {
    return {
      comments,
      createdAt,
      keyId,
      newText,
      suggestionId,
      text,
      type: 'replace',
      userId: suggestionData.userId,
    };
  }

  if (newText.length > 0) {
    return {
      comments,
      createdAt,
      keyId,
      newText,
      suggestionId,
      type: 'insert',
      userId: suggestionData.userId,
    };
  }

  if (text.length > 0) {
    return {
      comments,
      createdAt,
      keyId,
      suggestionId,
      text,
      type: 'remove',
      userId: suggestionData.userId,
    };
  }

  return null;
};

export const buildBlockDiscussionIndex = ({
  discussions,
  entries,
  getBlockLabel,
  getBlockNodeKey,
  getCommentId,
  getSuggestionData,
  getSuggestionDataList,
  getSuggestionId,
  getSuggestionKey,
  isBlockSuggestion,
  isDraftComment = () => false,
  isDate = () => false,
  isInlineEquation = () => false,
}: BuildBlockDiscussionIndexOptions): BlockDiscussionIndex => {
  const materializedDiscussions = discussions.map(
    (discussion) => structuredClone(discussion) as TDiscussion
  );
  const commentOwnerById = new Map<string, Path>();
  const commentOwnerNodeKeyById = new Map<string, NodeKey>();
  const suggestionOwnerById = new Map<string, Path>();
  const suggestionOwnerNodeKeyById = new Map<string, NodeKey>();
  const commentIds = new Set<string>();
  const suggestionEntriesById = new Map<string, SuggestionEntry[]>();
  const discussionsById = new Map(
    materializedDiscussions.map((discussion) => [discussion.id, discussion])
  );
  const topLevelNodeKeyByIndex = new Map<number, NodeKey>();

  if (getBlockNodeKey) {
    entries.forEach(([node, path]) => {
      if (path.length === 1 && ElementApi.isElement(node)) {
        topLevelNodeKeyByIndex.set(path[0], getBlockNodeKey(node));
      }
    });
  }
  const draftCommentNodeKeys = new Set<NodeKey>();

  entries.forEach(([node, path]) => {
    const blockPath = getTopLevelPath(path);
    const blockNodeKey = topLevelNodeKeyByIndex.get(path[0]);

    if (!blockPath) return;

    if (TextApi.isText(node)) {
      if (
        blockNodeKey &&
        isDraftComment(node) &&
        !draftCommentNodeKeys.has(blockNodeKey)
      ) {
        draftCommentNodeKeys.add(blockNodeKey);
      }
      const commentId = getCommentId(node);

      if (commentId) {
        commentIds.add(commentId);

        if (!commentOwnerById.has(commentId)) {
          commentOwnerById.set(commentId, blockPath);
          if (blockNodeKey) {
            commentOwnerNodeKeyById.set(commentId, blockNodeKey);
          }
        }
      }
    }

    getSuggestionIds(node, getSuggestionDataList, getSuggestionId).forEach(
      (suggestionId) => {
        if (!suggestionOwnerById.has(suggestionId)) {
          suggestionOwnerById.set(suggestionId, blockPath);
          if (blockNodeKey) {
            suggestionOwnerNodeKeyById.set(suggestionId, blockNodeKey);
          }
        }

        appendByKey(suggestionEntriesById, suggestionId, [node, path]);
      }
    );
  });

  const discussionsByBlock = new Map<string, TDiscussion[]>();
  const discussionsByNodeKey = new Map<NodeKey, TDiscussion[]>();

  materializedDiscussions.forEach((discussion) => {
    const ownerPath = commentOwnerById.get(discussion.id);

    if (!ownerPath || !commentIds.has(discussion.id) || discussion.isResolved) {
      return;
    }

    const resolvedDiscussion = {
      ...discussion,
      createdAt: new Date(discussion.createdAt),
    };

    appendByKey(discussionsByBlock, getBlockKey(ownerPath), resolvedDiscussion);
    const ownerNodeKey = commentOwnerNodeKeyById.get(discussion.id);

    if (ownerNodeKey) {
      appendByKey(discussionsByNodeKey, ownerNodeKey, resolvedDiscussion);
    }
  });

  const suggestionsByBlock = new Map<string, BlockResolvedSuggestion[]>();
  const suggestionsByNodeKey = new Map<NodeKey, BlockResolvedSuggestion[]>();

  suggestionEntriesById.forEach((suggestionEntries, suggestionId) => {
    const ownerPath = suggestionOwnerById.get(suggestionId);

    if (!ownerPath) return;

    const resolvedSuggestion = toResolvedSuggestion({
      discussionsById,
      entries: suggestionEntries,
      getSuggestionData,
      getSuggestionDataList,
      getBlockLabel,
      getSuggestionKey,
      id: suggestionId,
      isBlockSuggestion,
      isDate,
      isInlineEquation,
    });

    if (!resolvedSuggestion) return;

    appendByKey(suggestionsByBlock, getBlockKey(ownerPath), resolvedSuggestion);
    const ownerNodeKey = suggestionOwnerNodeKeyById.get(suggestionId);

    if (ownerNodeKey) {
      appendByKey(suggestionsByNodeKey, ownerNodeKey, resolvedSuggestion);
    }
  });

  const contentKeyByNodeKey = new Map<NodeKey, string>();

  topLevelNodeKeyByIndex.forEach((nodeKey) => {
    const nodeDiscussions = discussionsByNodeKey.get(nodeKey) ?? [];
    const nodeSuggestions = suggestionsByNodeKey.get(nodeKey) ?? [];
    const hasDraftComment = draftCommentNodeKeys.has(nodeKey);

    contentKeyByNodeKey.set(
      nodeKey,
      hasDraftComment ||
        nodeDiscussions.length > 0 ||
        nodeSuggestions.length > 0
        ? JSON.stringify([hasDraftComment, nodeDiscussions, nodeSuggestions])
        : ''
    );
  });

  return {
    contentKeyByNodeKey,
    discussionsByBlock,
    discussionsByNodeKey,
    draftCommentNodeKeys,
    suggestionsByBlock,
    suggestionsByNodeKey,
    topLevelNodeKeys: new Set(topLevelNodeKeyByIndex.values()),
  };
};
